.sunburst {
  transition-property: font-size;
  width: 100%;
  height: 100%;
  position: absolute;
  transition-duration: 0.2s;
}
.sunburst--interactive path {
  opacity: 0.2;
}
.sunburst .sunburst__slice {
  stroke: #ffffff;
  fill: transparent;
  fill-rule: evenodd;
}
.sunburst .sunburst__slice--selected {
  opacity: 1;
}
.sunburst .sunburst__slice--hidden {
  fill: none;
  fill-rule: nonzero;
}
.sunburst__slice-label {
  text-anchor: middle;
  pointer-events: none;
}
.sunburst__label {
  opacity: 0;
  transition-property: opacity;
  transition-duration: 0.2s;
  text-anchor: middle;
}
.sunburst__label--visible {
  opacity: 1;
}


